DROP DATABASE IF EXISTS universe;
CREATE DATABASE universe;
\connect universe

CREATE TABLE galaxy (galaxy_id SERIAL PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL, galaxy_types TEXT, age_in_millions_of_years INT NOT NULL, distance_from_earth NUMERIC, has_life BOOLEAN);
CREATE TABLE star (star_id SERIAL PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL, galaxy_id INT NOT NULL REFERENCES galaxy(galaxy_id), age_in_millions_of_years INT, mass NUMERIC, is_spherical BOOLEAN NOT NULL);
CREATE TABLE planet (planet_id SERIAL PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL, star_id INT NOT NULL REFERENCES star(star_id), has_life BOOLEAN NOT NULL, planet_types TEXT, distance_from_earth INT, radius NUMERIC);
CREATE TABLE moon (moon_id SERIAL PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL, planet_id INT NOT NULL REFERENCES planet(planet_id), is_spherical BOOLEAN, diameter_km INT, description TEXT);
CREATE TABLE constellation (constellation_id SERIAL PRIMARY KEY, name VARCHAR(40) UNIQUE NOT NULL, abbreviation VARCHAR(3) NOT NULL, star_count INT, is_zodiac BOOLEAN, description TEXT);
